def minimumPairRemoval(nums: List[int]) -> int:
    import heapq
    n = len(nums)
    if n <= 1:
        return 0
    val = list(nums)
    left = list(range(-1, n - 1))
    right = list(range(1, n + 1))
    alive = [True] * n
    bad = 0
    for i in range(n - 1):
        if val[i] > val[i + 1]:
            bad += 1
    heap = []
    for i in range(n - 1):
        heapq.heappush(heap, (val[i] + val[i + 1], i))
    ops = 0
    while bad > 0:
        s, i = heapq.heappop(heap)
        if i >= n or not alive[i]:
            continue
        j = right[i]
        if j >= n or not alive[j]:
            continue
        if val[i] + val[j] != s:
            continue
        ops += 1
        p = left[i]
        q = right[j]
        if val[i] > val[j]:
            bad -= 1
        if p >= 0 and alive[p] and val[p] > val[i]:
            bad -= 1
        if q < n and alive[q] and val[j] > val[q]:
            bad -= 1
        val[i] = val[i] + val[j]
        alive[j] = False
        right[i] = q
        if q < n:
            left[q] = i
        if p >= 0 and alive[p]:
            if val[p] > val[i]:
                bad += 1
            heapq.heappush(heap, (val[p] + val[i], p))
        if q < n and alive[q]:
            if val[i] > val[q]:
                bad += 1
            heapq.heappush(heap, (val[i] + val[q], i))
    return ops
